import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import pdf from 'pdf-parse';
import { Request, Response } from 'express';

interface ScanResult {
  matchScore: number;
  missingKeywords: string[];
  foundKeywords: string[];
}

export const analyzeResume = async (req: Request, res: Response) => {
  if (!req.file) return res.status(400).send('No file uploaded.');

  const { keywords } = req.body;
  const data = await pdf(req.file.buffer);
  const resumeText = data.text.toLowerCase();

  const foundKeywords = keywords.filter((k: string) => resumeText.includes(k.toLowerCase()));
  const matchScore = (foundKeywords.length / keywords.length) * 100;

  res.json({
    matchScore,
    foundKeywords,
    missingKeywords: keywords.filter((k: string) => !foundKeywords.includes(k))
  } as ScanResult);
};

import React from 'react';

export const MatchScoreGauge: React.FC<{ score: number }> = ({ score }) => {
  const radius = 40;
  const circumference = 2 * Math.PI * radius;
  const strokeDashoffset = circumference - (score / 100) * circumference;

  return (
    <div className="flex items-center justify-center relative">
      <svg className="transform -rotate-90 w-32 h-32">
        <circle className="text-gray-200" strokeWidth="8" stroke="currentColor" fill="transparent" r={radius} cx="64" cy="64" />
        <circle 
          className="text-indigo-600 transition-all duration-1000 ease-out"
          strokeWidth="8" strokeDasharray={circumference} strokeDashoffset={strokeDashoffset} 
          strokeLinecap="round" stroke="currentColor" fill="transparent" r={radius} cx="64" cy="64" 
        />
      </svg>
      <span className="absolute text-xl font-bold">{Math.round(score)}%</span>
    </div>
  );
};
